//! Cross-dispatch caller plugin.
//!
//! Hand-written test fixture (not generated by polyplugc). It registers the
//! `cross.caller@1` contract whose function 0 performs a plugin→plugin
//! **cross-call**: it invokes `cross.target@1` (provided by
//! `cross_target_plugin`) through `HostApi::call_guest_method` and returns the
//! target's result as its own output.
//!
//! State threading (no statics): the `HostApi` pointer the host hands to
//! `create_instance` is captured into a heap-owned `CallerInstance`. Function 0
//! reads the captured pointer from its instance handle — context flows through
//! `host` + instance data only, never through globals or thread-locals.

use polyplug_abi::AbiErrorCode;
use polyplug_abi::*;
use polyplug_utils::GuestContractId;

// ─── Cross-call wire types ────────────────────────────────────────────────────

/// Arguments accepted by `cross.caller`'s function 0 and forwarded verbatim to
/// `cross.target`'s `add`. Layout matches `cross_target_plugin::AddArgs`.
#[repr(C)]
pub struct AddArgs {
    pub a: u32,
    pub b: u32,
}

/// Heap-owned per-instance state. Holds the `HostApi` pointer captured at
/// `create_instance` so function 0 can issue the cross-call without any static
/// or thread-local storage.
#[repr(C)]
struct CallerInstance {
    host: *const HostApi,
}

// ─── Function 0: the cross-call ───────────────────────────────────────────────

/// Function 0: forward `add(a, b)` to `cross.target@1` via the host and return
/// its result.
///
/// Routing: build a `cross.target` instance handle (the target's `add` is
/// stateless and ignores instance data, so a non-null marker pointer satisfies
/// `host_call_guest_method`'s non-null-`data` precondition while the
/// `contract_id` selects the target contract), then call
/// `host->call_guest_method` for the target's function 0.
///
/// # Safety
/// `instance` must be a live `cross.caller` instance produced by
/// `create_instance`. `args` must point to a valid `AddArgs`; `out` to a valid
/// `u32`.
unsafe extern "C" fn caller_cross_add(
    instance: GuestContractInstance,
    args: *const (),
    out: *mut (),
    out_err: *mut AbiError,
) {
    let __result_err: AbiError = (|| {
        if instance.data.is_null() || args.is_null() || out.is_null() {
            return AbiError {
                code: AbiErrorCode::InvalidPointer as u32,
                message: string_view_null(),
            };
        }

        // SAFETY: `instance.data` was produced by this contract's `create_instance`
        // as a `Box<CallerInstance>` leaked via `Box::into_raw`; it is live for the
        // duration of the call and not aliased mutably.
        let state: &CallerInstance = unsafe { &*(instance.data as *const CallerInstance) };
        let host_ptr: *const HostApi = state.host;
        if host_ptr.is_null() {
            return AbiError {
                code: AbiErrorCode::InvalidPointer as u32,
                message: string_view_null(),
            };
        }
        // SAFETY: `host_ptr` was captured from a non-null `HostApi` the host passed
        // to `create_instance`; it stays valid for the runtime lifetime.
        let host: &HostApi = unsafe { &*host_ptr };

        // A stack marker provides a non-null `data` for the target instance handle.
        // The target's `add` is stateless and never dereferences it; the
        // `contract_id` is what routes the call to `cross.target`.
        let mut target_marker: u8 = 0;
        let target_instance: GuestContractInstance = GuestContractInstance {
            data: &mut target_marker as *mut u8 as *mut core::ffi::c_void,
            contract_id: GuestContractId::new("cross.target", 1),
        };

        // Out-param ABI: call_guest_method writes its AbiError through a trailing
        // pointer and returns void; this caller surfaces it by value.
        let mut err: AbiError = AbiError {
            code: AbiErrorCode::Ok as u32,
            message: string_view_null(),
        };
        // SAFETY: `call_guest_method` is a valid host function pointer. The target
        // function 0 expects `AddArgs` in / `u32` out, which `args`/`out` satisfy
        // (forwarded verbatim from this contract's own caller). A null arena selects
        // the native per-value path (the target uses native dispatch). `&mut err` is valid.
        unsafe {
            (host.call_guest_method)(
                host_ptr,
                target_instance,
                0,
                args as *const core::ffi::c_void,
                out as *mut core::ffi::c_void,
                core::ptr::null_mut(),
                &mut err as *mut AbiError,
            );
        }
        err
    })();
    if !out_err.is_null() {
        // SAFETY: out_err is non-null (just checked) and writable per the ABI contract.
        unsafe { out_err.write(__result_err) };
    }
}

// ─── Instance lifecycle ───────────────────────────────────────────────────────

/// Capture the host pointer into a heap-owned instance.
///
/// # Safety
/// `host` must be a valid non-null `HostApi` pointer for the runtime lifetime.
/// `_args` is unused.
unsafe extern "C" fn create_instance(
    _loader_data: VmLoaderData,
    host: *const HostApi,
    _args: *const (),
    out_instance: *mut GuestContractInstance,
) {
    let boxed: Box<CallerInstance> = Box::new(CallerInstance { host });
    if !out_instance.is_null() {
        // SAFETY: out_instance is non-null (just checked) and writable per the ABI contract.
        unsafe {
            out_instance.write(GuestContractInstance {
                data: Box::into_raw(boxed) as *mut core::ffi::c_void,
                contract_id: GuestContractId::new("cross.caller", 1),
            })
        };
    }
}

/// Destroy a previously created instance.
///
/// # Safety
/// `instance.data` must be a pointer returned by this contract's
/// `create_instance`, not yet destroyed.
unsafe extern "C" fn destroy_instance(
    _loader_data: VmLoaderData,
    _host: *const HostApi,
    instance: GuestContractInstance,
) {
    if instance.data.is_null() {
        return;
    }
    // SAFETY: `instance.data` was produced by `create_instance` via
    // `Box::into_raw`; reclaiming it once is sound.
    unsafe {
        drop(Box::from_raw(instance.data as *mut CallerInstance));
    }
}

// ─── Static Interface ──────────────────────────────────────────────────────────

#[repr(transparent)]
pub struct FnPtr(pub *const ());

// SAFETY: `FnPtr` wraps a 'static read-only function pointer; safe to share.
unsafe impl Send for FnPtr {}
// SAFETY: function pointers are inherently Sync (read-only 'static memory).
unsafe impl Sync for FnPtr {}

static CALLER_FNS: [FnPtr; 1] = [FnPtr(caller_cross_add as *const ())];

fn caller_interface() -> GuestContractInterface {
    GuestContractInterface {
        contract_id: GuestContractId::new("cross.caller", 1),
        contract_version: Version {
            major: 1,
            minor: 0,
            patch: 0,
        },
        dispatch_type: DispatchType::Native,
        create_instance,
        destroy_instance,
        dispatch: DispatchMechanisms {
            native: NativeDispatch {
                function_count: 1,
                functions: CALLER_FNS.as_ptr() as *const *const (),
            },
        },
    }
}

static DESCRIPTOR: PluginDescriptor = PluginDescriptor {
    name: StringView {
        ptr: b"cross_caller_plugin".as_ptr(),
        len: 19,
    },
    contract_name: StringView {
        ptr: b"cross.caller".as_ptr(),
        len: 12,
    },
    version: Version {
        major: 1,
        minor: 0,
        patch: 0,
    },
};

// ─── ABI Exports ───────────────────────────────────────────────────────────────

#[unsafe(no_mangle)]
pub extern "C" fn polyplug_abi_version() -> u32 {
    POLYPLUG_ABI_VERSION
}

/// Plugin init — registers the `cross.caller@1` contract.
///
/// # Safety
/// `host_abi` must be a valid non-null `HostApi` pointer; `ctx` must be a valid
/// non-null `BundleInitContext` pointer (both supplied by the host).
#[unsafe(no_mangle)]
pub unsafe extern "C" fn polyplug_init(
    host_abi: *const HostApi,
    ctx: *const BundleInitContext,
) -> AbiError {
    if host_abi.is_null() || ctx.is_null() {
        return AbiError {
            code: AbiErrorCode::Generic as u32,
            message: string_view_null(),
        };
    }
    // SAFETY: `host_abi` is non-null and provided by the host runtime.
    let host: &HostApi = unsafe { &*host_abi };
    let interface: GuestContractInterface = caller_interface();
    // Out-param ABI: register_guest_contract writes its AbiError through a
    // trailing pointer and returns void; init still surfaces it by value.
    let mut err: AbiError = AbiError {
        code: AbiErrorCode::Ok as u32,
        message: string_view_null(),
    };
    // SAFETY: `register_guest_contract` is a valid host function pointer.
    // `DESCRIPTOR` is 'static; `interface` outlives the synchronous call; &mut err is valid.
    unsafe {
        (host.register_guest_contract)(
            host_abi,
            &DESCRIPTOR as *const PluginDescriptor,
            &interface as *const GuestContractInterface,
            &mut err as *mut AbiError,
        );
    }
    err
}
